const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M7 17 17 7M7 7h10v10"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',save:'<path d="M6 3h12v18l-6-4-6 4z"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',room:'<path d="M4 21V3h12v18M2 21h20M16 6h4v15M12 12h.01"/>',chat:'<path d="M21 11c0 5-4 8-9 8H5l-3 3V11c0-5 4-8 10-8s9 3 9 8Z"/><path d="M7 11h10m-10 4h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',pin:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 4h.01"/>'};
const ic=n=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.book}</svg>`;
let assessments=[];let catalog=[],model=null,corpusEngine=null,results=[],pool=[],saved=[],lastRequest=0,neuralWorker=null,neuralScores=null,googleState='idle',googleError='',googleMore=false,nextOffset=0,modelStatus='Catalog semantic model',currentQuery='',chatBusy=false;
const state={page:'home',scope:'opensquare',mode:'hybrid',sort:'relevance',language:'any',access:'any',title:'',author:'',isbn:'',subject:'',from:'',to:'',limit:12,neural:false};
try{const a=JSON.parse(localStorage.getItem('library-next-saved')||'[]');if(Array.isArray(a))saved=a;}catch{}
try{const a=JSON.parse(localStorage.getItem('library-next-assessments')||'[]');if(Array.isArray(a))assessments=a;}catch{}
let conversation=newConversation(),assistantMode='contextual';const chatRecords=new Map();
const messages=[{role:'assistant',text:'Hi, I’m Library Next, your virtual library helper. Tell me what you need, and we’ll work through it together.'}];
function cover(b,cls=''){return `<div class="cover ${cls}" style="--cover:hsl(${(Number((b.isbn||'12345').slice(-4))||b.title.length*9)%360} 25% 32%)"><div class="cover-type"><small>${esc(b.publisher||b.source)}</small><strong>${esc(b.title)}</strong><i>${esc(b.authors)}</i></div>${b.cover?`<img src="${esc(b.cover)}" alt="Cover of ${esc(b.title)}" loading="lazy" onerror="this.remove()">`:''}</div>`;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
const link=(href,text,cls='')=>`<a class="${cls}" href="${esc(safeUrl(href))}" target="_blank" rel="noopener noreferrer">${text} ${ic('up')}</a>`;
function shell(){$('#app').innerHTML=`<div class="concept-bar"><span>NYU LIBRARIES <b>/</b> A CAPSTONE VISION</span><span>Independent sponsor proposal · Research prototype</span></div><header><button class="brand" data-page="home"><span class="monogram">N<span>${ic('up')}</span></span><span>NYU <strong>Library Next</strong><small>KNOWLEDGE. WITHOUT THE DISTANCE.</small></span></button><nav aria-label="Main navigation"><button data-page="home" class="active">Discover</button><button data-page="spaces">Study spaces</button><button data-page="help">Research help</button></nav><button class="saved-nav" data-page="saved" aria-label="Open saved books">${ic('save')}<span>My bookshelf</span><b id="saved-count">${saved.length}</b></button></header><main id="content"></main><footer><div><strong>NYU Library Next</strong><p>An independent capstone proposal for a more connected library.</p></div><div class="footer-links"><button data-page="proposal">Sponsor brief</button><button id="sources">Sources & search methods</button><a href="https://github.com/akshitashah04/Capstone" target="_blank" rel="noopener">Project on GitHub ↗</a></div><span>Concept, not an official NYU service. Holdings and room availability require NYU verification.</span></footer><button id="assistant-launch" class="assistant-launch">${ic('spark')} Ask Library Next <span>${ic('up')}</span></button><aside id="chat-panel" aria-label="Library Next assistant" hidden><div class="chat-head"><span class="chat-symbol">${ic('spark')}</span><div><strong>Ask Library Next</strong><small>Your anytime virtual library helper</small></div><button id="close-chat" aria-label="Close assistant">${ic('close')}</button></div><div class="chat-disclosure">Source-grounded guide · Does not access your account or book rooms</div><div id="chat-messages" aria-live="polite"></div><form id="chat-form"><label class="sr-only" for="chat-input">Message the library assistant</label><textarea id="chat-input" rows="1" maxlength="1000" placeholder="Tell me what you need…" autocomplete="off"></textarea><button aria-label="Send message">${ic('arrow')}</button></form></aside><dialog id="dialog"><button id="close-dialog" aria-label="Close dialog">${ic('close')}</button><div id="dialog-content"></div></dialog><div id="toast" role="status"></div>`;bindGlobal();page('home');renderMessages();}
function searchForm(){return `<form id="search-form"><div class="search-tabs" aria-label="Discovery scope"><button type="button" data-scope="all" class="${state.scope==='all'?'active':''}">${ic('search')} Include Google Books</button><button type="button" data-scope="opensquare" class="${state.scope==='opensquare'?'active':''}">${ic('book')} OpenSquare</button><button type="button" data-open-advanced>Advanced search ${ic('filter')}</button></div><div class="search-field"><label class="sr-only" for="query">Search by topic, title, author or question</label><input id="query" placeholder="Search books, ideas, authors…" maxlength="400" value="${esc(currentQuery)}"><button>Search books ${ic('arrow')}</button></div><div class="search-under"><span>${ic('spark')} Search by meaning. Stay grounded in sources.</span><label><input id="neural-toggle" type="checkbox" ${state.neural?'checked':''}> Neural reranking <span title="Downloads a pretrained model to your browser (approximately 25 MB).">ⓘ</span></label></div></form>`;}
function home(){const featured=['9781479888788','9781479807185','9781479882281'].map(id=>catalog.find(b=>b.isbn===id)).filter(Boolean);return `<section class="hero"><div class="hero-heading"><div class="eyebrow"><span></span> FOR EVERY QUESTION, A NEW POSSIBILITY</div><h1>A world of knowledge.<br><em>A place to begin.</em></h1><p>Find the book that moves your thinking forward.<br> Connect with the spaces, people, and ideas that help you get there.</p></div><div class="hero-illustration" aria-hidden="true"><div class="arch"><div class="arch-grid"></div><span class="orbit"></span><div class="floating-book book-one"><small>EXPLORE</small><strong>New<br>ways of<br>seeing.</strong><span>✳</span></div><div class="floating-book book-two"><small>DISCOVER</small><strong>The next<br>chapter.</strong><span>${ic('up')}</span></div><span class="art-badge">A LIBRARY OF POSSIBILITIES</span></div><span class="art-spark">✧</span></div><div class="hero-search">${searchForm()}</div></section><section class="discovery-trail"><span>FOLLOW YOUR CURIOSITY</span>${['Artificial intelligence and society','Climate-resilient cities','Migration and belonging'].map(q=>`<button data-query="${esc(q)}">${esc(q)} ↗</button>`).join('')}</section><section class="service-strip"><button data-page="spaces"><span class="service-icon">${ic('room')}</span><span><strong>Find your study space</strong><small>A quieter corner. A place to collaborate.</small></span>${ic('up')}</button><button data-chat="1"><span class="service-icon">${ic('chat')}</span><span><strong>A little research guidance</strong><small>Ask a question. Find a direction.</small></span>${ic('up')}</button><button data-page="help"><span class="service-icon">${ic('help')}</span><span><strong>Connect with a librarian</strong><small>Expert help when it matters.</small></span>${ic('up')}</button></section><section class="discovery-section"><div class="section-head"><div><div class="eyebrow">IDEAS WORTH SPENDING TIME WITH</div><h2>Discover beyond your discipline.</h2></div><button class="text-link" data-query="digital culture">Explore the collection ${ic('arrow')}</button></div><div class="featured-grid">${featured.map((b,i)=>`<button class="feature-book f${i}" data-detail="${esc(b.id)}"><span class="feature-category">${['TECHNOLOGY & SOCIETY','CULTURE & IDENTITY','MEDIA & COMMUNICATION'][i]}</span><div class="feature-content">${cover(b)}<div><h3>${esc(b.title)}</h3><p>${esc(b.subtitle)}</p><small>${esc(b.authors)}</small></div></div><span class="feature-bottom">OPEN ACCESS · NYU PRESS ${ic('up')}</span></button>`).join('')}</div></section><section class="perspective"><div class="perspective-number">01 <span>/ A NEW PERSPECTIVE</span></div><blockquote>“The best discoveries often start<br> with a better question.”</blockquote><div><p>Broader discovery. Clearer access. Human help.<br>A connected library experience, designed around you.</p><button data-page="proposal" class="text-link">Explore the proposal ${ic('arrow')}</button></div></section>`;}
function searchView(){return `<section class="search-page"><div class="page-eyebrow">DISCOVER / ${state.page==='saved'?'MY BOOKSHELF':'BOOKS & IDEAS'}</div><h1>${state.page==='saved'?'Your next chapter, saved.':'Follow the question.'}</h1>${searchForm()}<div class="results-layout"><aside class="refine"><div class="refine-head"><strong>${ic('filter')} Refine your search</strong><button id="reset-filters">Reset</button></div><label>Collection<select id="scope-filter"><option value="all" ${state.scope==='all'?'selected':''}>Google Books + OpenSquare</option><option value="google" ${state.scope==='google'?'selected':''}>Google Books</option><option value="opensquare" ${state.scope==='opensquare'?'selected':''}>OpenSquare only</option></select></label><label>Access<select id="access-filter"><option value="any">Any access</option><option value="full" ${state.access==='full'?'selected':''}>Full-view / open-access</option></select></label><label>Language<select id="language-filter">${[['any','Any language'],['en','English'],['es','Spanish'],['fr','French'],['de','German'],['zh','Chinese']].map(([v,l])=>`<option value="${v}" ${state.language===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="year-row"><label>From<input id="from-filter" type="number" min="1000" max="2100" placeholder="Any year" value="${esc(state.from)}"></label><label>To<input id="to-filter" type="number" min="1000" max="2100" placeholder="Any year" value="${esc(state.to)}"></label></div><label>Rank by<select id="mode-filter">${[['hybrid','Hybrid relevance'],['semantic','Semantic similarity'],['keyword','Keyword relevance']].map(([v,l])=>`<option value="${v}" ${state.mode===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="advanced-sidebar" data-open-advanced>Title, author, ISBN & subject ${ic('up')}</button><div class="refine-note">${ic('book')}<strong>${state.scope==='opensquare'?'The NYU Press bookshelf.':'A wider bookshelf.'}</strong><p>${state.scope==='opensquare'?'Search the complete OpenSquare collection by topic, title, author, or ISBN. Every book links to its original open-access page.':'Google Books discovers titles beyond NYU Press. Check NYU’s catalog separately for library access.'}</p></div></aside><div class="results-column"><div class="results-heading"><div><h2 id="results-title"></h2><p id="results-meta" aria-live="polite"></p></div><label class="sort-label">Sort<select id="sort-filter"><option value="relevance">Relevance</option><option value="newest" ${state.sort==='newest'?'selected':''}>Newest</option><option value="title" ${state.sort==='title'?'selected':''}>Title A–Z</option></select></label></div><div id="search-status" aria-live="polite"></div><div id="filter-summary"></div><div class="results-actions"><span id="model-status"></span><button class="text-link" id="assess-results">Rate results</button><button class="text-link" id="export-results">${ic('download')} Export</button></div><div id="results-list"></div><div class="load-controls"><button id="show-more" hidden>Show more matches ↓</button><button id="fetch-more" hidden>Search more Google Books results ↗</button></div></div></div></section>`;}
function roomView(){return `<section class="spaces-page"><div class="page-eyebrow">YOUR LIBRARY / STUDY SPACES</div><div class="space-intro"><div><div class="eyebrow">ROOM TO THINK. SPACE TOGETHER.</div><h1>Make room<br>for <em>good work.</em></h1><p>Plan a study session at Bobst, then check live availability<br>and complete your reservation in NYU’s official system.</p><div class="location-line">${ic('pin')} Bobst Library · 70 Washington Square South</div></div><div class="space-art" aria-hidden="true"><div class="space-window"></div><div class="space-table"></div><span>YOUR NEXT GOOD IDEA<br>COULD START HERE.</span></div></div><div class="space-layout"><form id="room-form" class="room-planner"><div class="eyebrow">LET’S PLAN YOUR SESSION</div><h2>A few details. A clear next step.</h2><div class="form-grid"><label>Date<input id="room-date" type="date" required></label><label>Start time <small>New York time</small><select id="room-start">${Array.from({length:30},(_,i)=>{const h=8+Math.floor(i/2),m=i%2?'30':'00';return `<option value="${String(h).padStart(2,'0')}:${m}">${h>12?h-12:h}:${m} ${h>=12?'PM':'AM'}</option>`}).join('')}</select></label><label>Duration<select id="room-duration">${[30,60,90,120,150,180].map(n=>`<option value="${n}" ${n===60?'selected':''}>${n} minutes</option>`).join('')}</select></label><label>Group size<select id="room-people"><option value="1">Just me</option>${[2,3,4,5,6].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} people</option>`).join('')}</select></label></div><p id="room-error" class="form-error" role="status"></p><button class="primary-button">Prepare my study plan ${ic('arrow')}</button><div id="room-plan"></div></form><aside class="room-policy"><span class="service-icon">${ic('room')}</span><h2>Know before you go.</h2><p>Group study rooms are for groups of two or more. Reserve up to three hours, once per day, within the 14-day booking window.</p><div class="availability-state"><span></span><strong>Live availability: NYU LibCal</strong><p>This prototype cannot read room inventory or confirm a booking. The official calendar is the source of truth.</p></div>${link(SERVICES.rooms.url,'Open the availability calendar','text-link')}${link(SERVICES.individual.url,'Studying solo? Individual rooms','text-link')}${link(SERVICES.rooms.policyUrl,'Read NYU’s room policies','source-link')}<p class="source-date">Policy checked November 14, 2026 · NYU NetID required to book.</p></aside></div></section>`;}
function helpView(){return `<section class="help-page"><div class="page-eyebrow">YOUR LIBRARY / RESEARCH HELP</div><h1>You don’t have to<br><em>figure it out alone.</em></h1><p class="page-lede">Start here. We’ll help you find the right next step.</p><div class="help-grid"><button class="help-card" data-chat="1">${ic('spark')}<h2>Ask Library Next</h2><p>Find book suggestions and navigate library services with a source-grounded guide.</p><span>Start a conversation ${ic('arrow')}</span></button><a class="help-card" href="${SERVICES.help.url}" target="_blank" rel="noopener">${ic('chat')}<h2>Ask a librarian</h2><p>For expert research advice, complex questions, and account-specific help, connect with NYU.</p><span>Visit NYU Libraries ${ic('up')}</span></a><a class="help-card" href="https://guides.nyu.edu/" target="_blank" rel="noopener">${ic('book')}<h2>Find a research guide</h2><p>Explore subject guides, databases, and starting points created by NYU librarians.</p><span>Explore NYU research guides ${ic('up')}</span></a></div><section class="service-directory"><h2>The right service, one step closer.</h2>${Object.values(SERVICES).filter(s=>s!==SERVICES.individual).map(s=>`<div><span><strong>${esc(s.title)}</strong><p>${esc(s.text)}</p></span>${link(s.url,'Open official service','text-link')}</div>`).join('')}</section></section>`;}
function proposalView(){return `<section class="proposal-page"><div class="page-eyebrow">NYU LIBRARIES / SPONSOR PROPOSAL</div><div class="eyebrow">A CONNECTED DISCOVERY EXPERIENCE</div><h1>Beyond a search box.<br><em>A library that connects.</em></h1><p class="page-lede">A separate proposal alongside the original OpenSquare prototype. Broader discovery, transparent ranking, and useful paths to library services.</p><div class="proposal-pillars"><div><b>01</b><h2>Discover with context</h2><p>Google Books candidates plus the 329-book OpenSquare snapshot. Title, author, ISBN, language, year, access, and ranking controls.</p></div><div><b>02</b><h2>Explain the result</h2><p>Exact-title and ISBN priority, candidate-level relevance signals, optional MiniLM semantic reranking, and explicit access labels.</p></div><div><b>03</b><h2>Connect to action</h2><p>A book-and-services assistant, a personal bookshelf, and an honest handoff to Bobst’s live reservation system.</p></div></div><h2>What is working, and what comes next?</h2><div class="capability-table"><div class="table-row table-head"><strong>Capability</strong><strong>This prototype</strong><strong>Sponsor integration</strong></div>${[['Book discovery','Google Books API adapter + OpenSquare snapshot','API key and quota for reliable Google Books access'],['Semantic ranking','Corpus LSA; optional in-browser MiniLM model','Librarian judgments, held-out evaluation, model selection'],['Book access','Publisher/Google access metadata and catalog handoff','NYU Alma/Primo holdings and entitlement API'],['Library assistant','Contextual free-text chat, book follow-ups, service sources','Optional Gemini reply key and approved knowledge base'],['Bobst rooms','In-chat session collection; prepared availability and recheck adapter','Read-only LibCal OAuth access and room category IDs; official NYU checkout'],['Account services','Official links only; no account data','Approved NYU authentication and account APIs']].map(row=>`<div class="table-row">${row.map(c=>`<span>${esc(c)}</span>`).join('')}</div>`).join('')}</div><h2>Quality is a research question.</h2><p class="body-copy">A larger catalog alone does not ensure accurate results. Before claiming an improvement over the NYU beta, collect librarian relevance judgments, freeze a test set, and compare known-item, thematic, paraphrase, negation, and out-of-domain queries. Measure Recall@10, nDCG@10, MRR, latency, and failures. Google Books is a candidate source, not a replacement for NYU’s licensed discovery infrastructure.</p><div class="proposal-callout"><h3>Inspiration, without unsupported claims.</h3><p>Harvard’s library experience separates discovery, access, services, and research support. This proposal follows those usability principles; it does not claim equivalent collection coverage, institutional integration, or better retrieval quality.</p>${link('https://library.harvard.edu/','Harvard Library reference','text-link')}</div><h2>Project materials</h2><p class="body-copy">The supplied NYU NLP beta could not be accessed in this environment. The kickoff deck, shared beta-testing spreadsheet, and portal benchmarking PDFs were reviewed. The local relevance-assessment form supports the kickoff’s feedback-loop goal. Their AI-risk, warming, classical-music, and architecture failure cases inform targeted regression checks; they do not establish current beta behavior or prove that this proposal performs better. The spreadsheet marks an earlier stale-query input issue as fixed.</p><div class="proposal-links">${link('https://github.com/akshitashah04/Capstone','Original prototype + proposal source','text-link')}${link('https://nlp-metadata-library-project-web-g-karms-nlp-dev.apps.cloud.rt.nyu.edu/','Sponsor’s existing NLP beta','text-link')}${link('https://drive.google.com/drive/u/1/folders/1a41RvfasCv-KA-QfSmzUc5QMe7vWCh2m','Shared sponsor materials','text-link')}</div></section>`;}
function page(name){state.page=name;document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#content').innerHTML=name==='home'?home():name==='spaces'?roomView():name==='help'?helpView():name==='proposal'?proposalView():searchView();bindPage();if(['search','saved'].includes(name))renderResults();if(name==='spaces'){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('#room-date').value=today;$('#room-date').min=today;const max=new Date(Date.parse(today+'T12:00:00Z')+14*86400000);$('#room-date').max=max.toISOString().slice(0,10);}window.scrollTo({top:0,behavior:'instant'});}
function filters(){return {...state};}
function resultCard(r){const b=r.book,isSaved=saved.some(x=>x.id===b.id);return `<article class="result-card">${cover(b)}<div class="result-info"><div class="book-overline">${esc(b.sources.join(' + '))} <span>·</span> ${b.year||'Year not supplied'}</div><h3><button data-detail="${esc(b.id)}">${esc(b.title)}</button></h3>${b.subtitle?`<p class="subtitle">${esc(b.subtitle)}</p>`:''}<p class="author">${esc(b.authors)}</p><p class="book-description">${esc(b.description||'Description not supplied by the source.')}</p><div class="book-tags"><span class="${b.fullView?'access-full':''}">${esc(b.accessStatus)}</span>${b.subjects.slice(0,2).map(s=>`<span>${esc(s)}</span>`).join('')}</div><details class="match-details"><summary>${ic('spark')} ${r.exact?'Exact title match':r.isbnMatch?'Exact ISBN match':'Why this book?'}</summary><p>${r.exact||r.isbnMatch?'An exact identifier/title match takes priority over ranking scores. ':''}Semantic cosine ${r.semantic.toFixed(3)} (${esc(r.semanticModel)}); normalized BM25 ${r.lexical.toFixed(3)}; provider-rank signal ${r.provider.toFixed(3)}. Weights: ${(r.weights.semantic*100).toFixed(1)}% semantic, ${(r.weights.lexical*100).toFixed(1)}% keyword${r.weights.provider?`, ${(r.weights.provider*100).toFixed(1)}% Google rank`:'. Google rank does not apply to this record'}.</p><p>These are retrieval signals, not confidence percentages. Scores are relative to the retrieved candidate set. NYU holdings have not been checked.</p></details></div><div class="result-rail"><button class="save-book ${isSaved?'is-saved':''}" data-save="${esc(b.id)}" aria-label="${isSaved?'Remove':'Save'} ${esc(b.title)}" aria-pressed="${isSaved}">${ic(isSaved?'check':'save')}</button>${currentQuery?`<span class="result-score"><strong>${r.score.toFixed(3)}</strong><small>${r.isbnMatch?'EXACT ISBN':r.exact?'EXACT TITLE':'MATCH SCORE'}</small></span>`:''}<button class="text-link" data-detail="${esc(b.id)}">View book ${ic('arrow')}</button></div></article>`;}
function renderResults(){let candidates=state.page==='saved'?saved:pool;results=rankBooks(candidates,currentQuery,filters(),model,neuralScores);if(!$('#results-list'))return;if(!currentQuery&&state.page!=='saved')results.sort((a,b)=>(b.book.year||0)-(a.book.year||0));$('#results-title').textContent=state.page==='saved'?'My bookshelf':currentQuery?`Results for “${currentQuery}”`:'Start with an idea';$('#results-meta').textContent=`${results.length} matching ${results.length===1?'book':'books'} from ${candidates.length} ${state.scope==='opensquare'&&state.page!=='saved'?'OpenSquare books':'retrieved records'}${state.page==='saved'?' saved on this browser':''}`;$('#model-status').textContent=state.neural?modelStatus:`${state.mode==='keyword'?'Keyword ranking':'Catalog semantic + keyword ranking'}`;$('#search-status').innerHTML=googleState==='loading'?'<div class="status-banner loading"><span class="spinner"></span> Searching Google Books. OpenSquare matches are ready below.</div>':googleState==='error'?`<div class="status-banner warning">Google Books is unavailable for this request. ${esc(googleError)} ${state.scope==='google'?'No new Google Books records were loaded.':pool.some(b=>b.sources.includes('Google Books'))?'Previously retrieved results remain below.':'Showing any available OpenSquare matches below.'} <button id="retry-google">Retry Google Books</button></div>`:googleState==='empty'?'<div class="status-banner">Google Books returned no titles for this query. Try fewer constraints or a different phrase.</div>':googleState==='success'?'<div class="status-banner success">Google Books results retrieved for this query. Access labels come from source metadata; check the NYU catalog separately for borrowing access.</div>':state.scope==='opensquare'?'<div class="status-banner collection-status">Searching the complete OpenSquare collection. Open-access NYU Press books, with original publisher descriptions.</div>':'';$('#filter-summary').innerHTML=['title','author','isbn','subject','from','to'].filter(k=>state[k]).map(k=>`<span class="filter-chip">${k}: ${esc(state[k])}</span>`).join('');$('#results-list').innerHTML=results.length?results.slice(0,state.limit).map(resultCard).join(''):`<div class="empty-state">${ic('search')}<h3>${state.page==='saved'?'A good book is worth coming back to.':'A new direction might help.'}</h3><p>${state.page==='saved'?'Save a book from your search results and find it here.':'No matches in the retrieved candidate set. Broaden the topic, clear filters, or search more Google Books results. This catalog cannot answer every query.'}</p>${state.page==='saved'?'<button class="primary-button" data-page="home">Discover books</button>':link(`https://books.google.com/books?q=${encodeURIComponent(currentQuery)}`,'Try this search on Google Books','text-link')}</div>`;$('#show-more').hidden=results.length<=state.limit;$('#fetch-more').hidden=!googleMore||state.page==='saved';$('#saved-count').textContent=saved.length;$('#export-results').disabled=!results.length;}
async function getGoogle(query,offset=0,overrideFilters=null){
 const f=overrideFilters||filters(),direct=buildGoogleUrl(query,f,offset),apiUrl=new URL('api/books',new URL(import.meta.env.BASE_URL,location.href));
 for(const[k,v]of Object.entries({q:query,title:f.title,author:f.author,isbn:f.isbn,subject:f.subject,language:f.language,access:f.access,start:offset,order:f.sort==='newest'?'newest':'relevance'}))if(v!==''&&v!==undefined)apiUrl.searchParams.set(k,String(v));
 let response,data,proxyError=null,tryDirect=false;
 try{response=await fetch(apiUrl,{signal:AbortSignal.timeout(14000)});if(response.status===404||response.headers.get('content-type')?.includes('text/html'))tryDirect=true;else{data=await response.json();if(response.ok&&!data.error)return data;proxyError=new Error(data.error||'Google Books is unavailable.');tryDirect=data.directFallbackAllowed===true;}}
 catch{proxyError=new Error('The Google Books connection could not be reached.');tryDirect=true;}
 if(tryDirect){try{const directResponse=await fetch(direct,{signal:AbortSignal.timeout(14000)});if(directResponse.ok){const result=await directResponse.json();if(!result.error)return result;}}catch{}}
 throw proxyError||new Error('Google Books could not load. A project API key may be required.');
}

function openCandidates(q){if(state.isbn)return catalog.filter(b=>b.isbn.replace(/-/g,'')===state.isbn.replace(/[\s-]/g,''));q=analyzeQuery(q).normalized.replace(/global warming/ig,'climate change global warming');const opts={mode:'hybrid',from:Number(state.from)||0,to:Number(state.to)||9999,author:state.author};return corpusEngine.search(state.isbn?'':q,opts).rows.slice(0,60).map(r=>catalog[r.index]);}
async function search(q,{more=false,fromChat=false}={}){q=q.trim();if(q.length>400){toast('Please keep your query under 400 characters.');return;}if(state.from&&state.to&&Number(state.from)>Number(state.to)){toast('The start year must be before the end year.');return;}try{if(q||state.title||state.author||state.isbn||state.subject)buildGoogleUrl(q,filters(),0);}catch(e){toast(e.message);return;}if(analyzeQuery(q).ambiguous911){showDialog(`<div class="eyebrow">LET’S MAKE SURE WE MEAN THE SAME THING</div><h2>What does “911” refer to?</h2><p>Choose a direction so unrelated topics do not get mixed together.</p><div class="detail-actions"><button class="primary-button" data-query="September 11 attacks and their aftermath">September 11 attacks</button><button class="primary-button" data-query="emergency response dispatch">Emergency response</button></div>`);return;}currentQuery=q;const id=++lastRequest;state.limit=12;neuralScores=null;googleState='idle';googleError='';const hasQuery=Boolean(q||state.title||state.author||state.isbn||state.subject);if(!more){nextOffset=0;pool=state.scope==='google'?[]:state.scope==='opensquare'?catalog:hasQuery?openCandidates(q||state.title||state.author||state.subject):catalog;}state.page='search';if(!fromChat)page('search');else if($('#results-list'))renderResults();const url=new URL(location.href);url.search=`?scope=${encodeURIComponent(state.scope)}${q?'&q='+encodeURIComponent(q):''}`;history.replaceState(null,'',url);if(state.scope!=='opensquare'&&hasQuery){googleState='loading';renderResults();try{const data=await getGoogle(q,nextOffset);if(id!==lastRequest)return;const items=(data.items||[]).map((b,i)=>normalizeGoogle(b,nextOffset+i)).filter(Boolean);pool=deduplicate([...pool,...items]);googleMore=items.length===40&&nextOffset<200;nextOffset+=40;googleState=items.length?'success':'empty';}catch(error){if(id!==lastRequest)return;googleState='error';googleError=error.message;googleMore=false;}renderResults();}else{googleMore=false;renderResults();}if(state.neural&&hasQuery)runNeural(id);if(fromChat)return results.slice(0,3);}
function runNeural(id){if(!neuralWorker){neuralWorker=new Worker(new URL('./neural-worker.js',import.meta.url),{type:'module'});neuralWorker.onmessage=({data})=>{if(!state.neural)return;if(data.id&&data.id!==lastRequest)return;if(data.type==='result'){neuralScores={scores:new Map(data.scores)};modelStatus='MiniLM neural reranking active';renderResults();}else if(data.type==='error'){modelStatus='Neural model unavailable · using catalog LSA';renderResults();}else if(data.type==='ranking'){modelStatus=`Neural reranking ${data.done}/${data.total} candidates`;renderResults();}else if(data.type==='progress'){modelStatus='Downloading semantic model…';if($('#model-status'))$('#model-status').textContent=modelStatus;}};neuralWorker.onerror=()=>{modelStatus='Neural model unavailable · using catalog LSA';renderResults();};}modelStatus='Loading neural semantic model…';renderResults();const candidates=rankBooks(pool,currentQuery,filters(),model).slice(0,60).map(r=>({id:r.book.id,text:textFor(r.book)}));neuralWorker.postMessage({id,query:currentQuery,books:candidates});}
function advanced(){showDialog(`<div class="eyebrow">MAKE YOUR SEARCH MORE PRECISE</div><h2>A little detail goes a long way.</h2><form id="advanced-form"><div class="form-grid">${[['title','Title contains'],['author','Author or editor'],['isbn','ISBN'],['subject','Subject category']].map(([k,l])=>`<label>${l}<input name="${k}" value="${esc(state[k])}" maxlength="150" placeholder="${k==='isbn'?'10 or 13 characters':'Optional'}"></label>`).join('')}<label>Published from<input name="from" type="number" min="1000" max="2100" value="${esc(state.from)}" placeholder="Any year"></label><label>Published through<input name="to" type="number" min="1000" max="2100" value="${esc(state.to)}" placeholder="Any year"></label></div><p>These fields combine with your topic. ISBN searches target the identifier directly. Year and title/author filters are applied to the retrieved candidate set, which is not the entire Google Books catalog.</p><p class="form-error" id="advanced-error"></p><button class="primary-button">Apply & search ${ic('arrow')}</button></form>`);$('#advanced-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.from&&data.to&&Number(data.from)>Number(data.to)){$('#advanced-error').textContent='The start year must come before the end year.';return;}try{buildGoogleUrl($('#query')?.value||currentQuery,{...state,...data},0);}catch(err){$('#advanced-error').textContent=err.message;return;}Object.assign(state,data);$('#dialog').close();search($('#query')?.value||currentQuery);};}
function findBook(id){if(chatRecords.has(id))return chatRecords.get(id);return pool.find(b=>b.id===id)||catalog.find(b=>b.id===id)||saved.find(b=>b.id===id);}
function bookDetail(id){const b=findBook(id);if(!b)return;const catalogUrl=`https://search.library.nyu.edu/discovery/search?vid=01NYU_INST:NYU&query=any,contains,${encodeURIComponent(b.isbn||b.title)}`;showDialog(`<div class="detail-top">${cover(b)}<div><div class="eyebrow">${esc(b.sources.join(' + '))} · ${b.year||'YEAR NOT SUPPLIED'}</div><h2>${esc(b.title)}</h2><p class="detail-subtitle">${esc(b.subtitle)}</p><p>${esc(b.authors)}</p><div class="detail-actions">${link(b.sourceUrl,'View original record','primary-link')}${link(catalogUrl,'Check NYU catalog','text-link')}</div></div></div><div class="access-notice">${ic('book')}<div><strong>${esc(b.accessStatus)}</strong><p>NYU ownership, borrowing eligibility, and licensed full-text access have not been checked. Google Books previews may depend on location and publisher permissions.</p></div></div><h3>About this book</h3><p class="full-description">${esc(b.description||'The source did not supply a description.')}</p><dl><dt>Author(s)</dt><dd>${esc(b.authors)}</dd><dt>Publisher</dt><dd>${esc(b.publisher||'Not supplied')}</dd><dt>ISBN</dt><dd>${esc(b.isbn||'Not supplied')}</dd><dt>Language</dt><dd>${esc(b.language)}</dd><dt>Subjects</dt><dd>${esc(b.subjects.join(' · ')||'Not supplied')}</dd></dl><div class="detail-actions"><button class="primary-button" data-save="${esc(b.id)}">${ic('save')} ${saved.some(s=>s.id===id)?'Remove from bookshelf':'Save to my bookshelf'}</button><button class="text-link" data-cite="${esc(b.id)}">Copy basic citation ${ic('up')}</button></div>`);}
function sources(){showDialog(`<div class="eyebrow">TRANSPARENT BY DESIGN</div><h2>Know what you’re searching.</h2><h3>Books, beyond one collection</h3><p>Google Books is queried on demand, with up to 40 new records per request and 240 candidates per search session. OpenSquare contributes a 329-record snapshot of real NYU Press metadata. Duplicate editions are merged by ISBN or matching title and author. Results shown are from retrieved candidates, not every book on the internet.</p><h3>Meaning, words, and exact matches</h3><p>OpenSquare hybrid ranking combines two-thirds semantic cosine and one-third normalized BM25. Google-only records use 60% semantic cosine, 30% BM25, and 10% Google rank. OpenSquare books are not penalized for having no Google ranking signal. Exact title and ISBN matches take priority. The default semantic model is 96-dimensional LSA trained on OpenSquare descriptions. It has limited vocabulary coverage for topics beyond that corpus.</p><p>Optional neural reranking downloads the quantized <strong>Xenova/all-MiniLM-L6-v2</strong> model to your browser, then compares the query with up to 60 candidate descriptions. This is semantic metadata search, not full-text search. The model requires access to Hugging Face and JavaScript delivery services and can fail; the interface reports the active model. Enabling it permits your browser to download those public model resources.</p><h3>When a match is too weak</h3><p>Known beta-test topics (AI risk, climate change, classical music, and architecture) require topic evidence in candidate metadata. This conservative check can omit relevant books whose metadata uses different wording. Ambiguous “911” prompts ask for clarification. These are targeted regression safeguards, not a general guarantee of accuracy.</p><h3>Scores are not certainty</h3><p>A score of 0.650 is not “65% accurate.” A score above 0.9 indicates very close metadata similarity and is uncommon for a short thematic question; exact-title and ISBN matches are also labeled separately. Results are never rescaled to make the best match automatically score 1.0. Scores depend on the candidate set and model. No model guarantees the right book for every query. Candidate source, snippets, titles, authors, and access metadata help you judge a match.</p><h3>A guide, with boundaries</h3><p>The chat assistant routes requests to retrieved books and a small, source-linked NYU services knowledge base. It remembers the current conversation and uses source-grounded library workflows. Optional generative wording can be enabled with a separate Gemini API key; the current mode is shown in the chat. It cannot access your NYU account. Room chat collects dates and times in New York time. The prepared LibCal integration can display availability and recheck a selected room once NYU supplies authorized API credentials. Until then, it does not list unverified rooms as available. Final identity verification and booking take place on NYU’s official room page.</p><h3>Sources and privacy</h3><div class="source-list">${link('https://developers.google.com/books/docs/v1/using','Google Books API documentation')}${link('https://github.com/NYULibraries/dlts-open-square','Published OpenSquare catalog')}${Object.values(SERVICES).map(s=>link(s.url,esc(s.title))).join('')}</div><p>Public book queries go to Google Books through the hosted proxy or, on GitHub Pages, directly from your browser. Chat messages remain in memory in this app. Book queries may go to Google Books, and structured room requests go to the room adapter. If the chat shows Google Gemini as active, short conversation context is also sent to that provider for source-grounded reply wording. Saved books and optional relevance assessments stay in this browser’s local storage. Source records and thumbnails are third-party content. Do not submit private personal or account information.</p>`);}
function showDialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();$('#dialog').scrollTop=0;}
function openChat(){$('#chat-panel').hidden=false;renderMessages();$('#chat-input').focus();}
function apiPath(path){return new URL(path.replace(/^\//,''),new URL(import.meta.env.BASE_URL,location.href)).href;}
function renderMessages(){
 $('#chat-messages').innerHTML=messages.map((m,i)=>`<div class="message ${m.role}"><div class="message-label">${m.role==='assistant'?'LIBRARY NEXT':'YOU'}</div><p>${esc(m.text)}</p>${m.roomRequest?`<div class="chat-request-summary">${ic('room')}<span>${esc(formatRoomRequest(m.roomRequest))}${m.roomRequest.people>1?`<small>${m.roomRequest.people} people</small>`:''}</span></div>`:''}${m.books?.length?`<div class="chat-books">${m.books.map((b,j)=>`<button data-detail="${esc(b.id)}"><span class="chat-result-number">${j+1}</span><strong>${esc(b.title)}</strong><span>${esc(b.authors)} · ${b.year||'Year not supplied'}</span>${b.description?`<p>${esc(b.description.slice(0,150))}${b.description.length>150?'…':''}</p>`:''}<small>${esc(b.sources.join(' + '))} · ${esc(b.accessStatus)}</small></button>`).join('')}</div>`:''}${m.bookSearch?`<button class="chat-action" data-chat-results="${i}">See more results for “${esc(m.bookSearch.query)}” ${ic('arrow')}</button>`:''}${m.rooms?.length?`<div class="chat-rooms">${m.rooms.map((room,j)=>`<article><div><span class="chat-room-available">Available at last check</span><h3>${j+1}. ${esc(room.name)}</h3><p>${room.capacity?`${room.capacity} ${room.capacity===1?'person':'people'} · `:''}${esc(room.location||'Bobst Library')}</p>${room.accessible?'<small>Accessible room</small>':''}</div><button class="chat-select-room" data-chat-room="${esc(room.id)}">Select room ${ic('arrow')}</button></article>`).join('')}<p class="chat-availability-note">${m.checkedAt?`Checked ${esc(new Date(m.checkedAt).toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'}))} New York time. `:''}A room is not held until NYU confirms your reservation.</p></div>`:''}${m.checkout?`<div class="chat-checkout"><strong>${esc(m.checkout.room.name)}</strong><p>Your selection was rechecked. Continue to NYU’s official room page to sign in with your NetID and submit the reservation. NYU may ask you to select the times again.</p><a href="${esc(m.checkout.checkoutUrl)}" target="_top" rel="noopener" class="primary-link">Continue with NYU NetID ${ic('up')}</a><small>Not booked or held yet. Look for confirmation from NYU.</small></div>`:''}${m.service?link(SERVICES[m.service].url,esc(SERVICES[m.service].title),'chat-source'):''}${m.bookDetail?`<button class="chat-action" data-detail="${esc(m.bookDetail)}">Open this book’s record ${ic('arrow')}</button>`:''}</div>`).join('')+(chatBusy?'<div class="message assistant chat-thinking"><span class="thinking-dots"><i></i><i></i><i></i></span><p>One moment—I’m working on that.</p></div>':'');
 $('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;$('#chat-form button').disabled=chatBusy;
}
async function composeReply(message,reply){if(assistantMode!=='generative'||reply.roomRequest||reply.checkout||reply.question||reply.critical)return reply;try{const response=await fetch(apiPath('api/assistant/reply'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,draft:reply.text,history:messages.filter(m=>!m.sensitive).slice(-4).map(m=>({role:m.role,text:m.text})),facts:{books:reply.books?.map(b=>({title:b.title,author:b.authors,year:b.year})),service:reply.service?SERVICES[reply.service].title:null}}),signal:AbortSignal.timeout(9000)});if(response.ok){const data=await response.json();if(data.mode==='generative'&&typeof data.text==='string')return {...reply,text:data.text};}}catch{}return reply;}
async function retrieveChatBooks(book){const f={mode:'hybrid',sort:'relevance',language:'any',access:'any',...book.filters};const local=book.scope==='google'?[]:rankBooks(catalog,book.query,f,model).filter(r=>r.priority||r.score>=.25);const localExact=local.some(r=>r.exact||r.isbnMatch);let candidates=local.map(r=>r.book),sourceError=false,actualScope=book.scope;
 if(book.scope==='all'||book.scope==='google'||(!localExact&&book.mode!=='topic')||(!localExact&&local.length<3)){try{const data=await getGoogle(book.query,0,f);const extra=(data.items||[]).map(normalizeGoogle).filter(Boolean);candidates=deduplicate([...candidates,...extra]);if(extra.length)actualScope=book.scope==='google'?'google':'all';}catch{sourceError=true;}}
 const rows=rankBooks(candidates,book.query,f,model).filter(r=>r.priority||r.score>=.2||r.book.source==='Google Books');for(const r of rows)chatRecords.set(r.book.id,r.book);if(chatRecords.size>160){for(const key of [...chatRecords.keys()].slice(0,chatRecords.size-160))chatRecords.delete(key);}conversation.book={...book,scope:actualScope};conversation.lastBooks=rows.map(r=>r.book);conversation.bookOffset=3;conversation.visibleBooks=conversation.lastBooks.slice(0,3);return {rows,sourceError,scope:actualScope};}
async function lookupChatRooms(room){const response=await fetch(apiPath('api/rooms/availability'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(room),signal:AbortSignal.timeout(22000)});if(response.headers.get('content-type')?.includes('application/json'))return response.json();return {status:'integration-required',live:false,error:'The live room connection is not enabled on this host yet.'};}
async function selectChatRoom(id){if(chatBusy||!conversation.roomResults?.live)return;const room=conversation.roomResults.rooms.find(r=>r.id===id);if(!room)return;messages.push({role:'user',text:`I’d like ${room.name}.`});chatBusy=true;renderMessages();try{const response=await fetch(apiPath('api/rooms/checkout'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...conversation.room,roomId:id}),signal:AbortSignal.timeout(22000)});const data=await response.json();if(response.ok&&data.status==='ready-for-official-checkout'&&data.confirmed===false&&/^https:\/\/nyu\.libcal\.com\/space\/\d+$/.test(data.checkoutUrl)){conversation.selectedRoom=data.room;messages.push({role:'assistant',text:'That room is ready for the next step. NYU will verify your eligibility and finish the booking on its official page.',roomRequest:conversation.room,checkout:data,critical:true});}else{messages.push({role:'assistant',text:data.error||'I couldn’t recheck that room. It isn’t booked; let’s try the availability search again.',roomRequest:conversation.room,critical:true});}}catch{messages.push({role:'assistant',text:'I couldn’t reach NYU to recheck that room. No booking has been made. Please try again in a moment.',critical:true});}chatBusy=false;renderMessages();}
async function chat(message){message=message.trim();if(!message||chatBusy)return;openChat();messages.push({role:'user',text:message});chatBusy=true;renderMessages();const plan=planTurn(message,conversation);if(plan.intent==='privacy')messages[messages.length-1].sensitive=true;let reply;
 try{
 if(plan.intent==='greeting')reply={text:'Hi! I’m here to help. Tell me what you’re looking for, and we’ll take it from there.'};
 else if(plan.intent==='identity')reply={text:'I’m Library Next, a virtual library helper—not a human librarian. I can help you find books and work through library tasks, and point you to NYU staff when you need them.'};
 else if(plan.intent==='thanks')reply={text:'You’re welcome! If anything else comes up while you’re studying, just ask.'};
 else if(plan.intent==='privacy')reply={text:'You don’t need to share your NYU email, NetID, or password here. Enter your sign-in details only on NYU’s official page after choosing a room. I can keep helping with your search without those details.',critical:true};
 else if(plan.intent==='service'){conversation.topic='services';reply={text:plan.service==='hours'?'Bobst is at 70 Washington Square South. I don’t have a live hours feed, and hours can vary by floor and service. NYU’s location page has the current schedule.':plan.service==='borrow'?'I can help you get to the right place for borrowing or renewals. Your current loans, due dates, and fines are private, so you’ll need your official NYU library account for those.':'For detailed research advice or account questions, an NYU librarian is the best person to help. You can reach Ask a Librarian from NYU Libraries’ site.',service:plan.service};}
 else if(plan.intent==='rooms'){conversation.topic='rooms';conversation.room=plan.room;conversation.selectedRoom=null;conversation.roomResults=null;if(plan.question){reply={text:plan.question,question:true};}else{let data;try{data=await lookupChatRooms(plan.room);}catch{data={status:'provider-unavailable',live:false};}if(data.live===true&&Array.isArray(data.rooms)){conversation.roomResults=data;conversation.roomOffset=3;conversation.visibleRooms=data.rooms.slice(0,3);reply={text:data.rooms.length?`I found ${data.rooms.length===1?'a room':`${data.rooms.length} rooms`} showing availability for your whole session. Pick one you like, and I’ll recheck it before you continue to NYU sign-in.`:'No rooms are showing as available for that entire session. Would a different time or date work for you?',roomRequest:plan.room,rooms:data.rooms.slice(0,3),checkedAt:data.checkedAt,critical:true};}else{reply={text:data.status==='integration-required'?'I’ve got your study session ready. Live Bobst availability isn’t connected yet, so I can’t honestly tell you which rooms are free or make a booking. I’ll keep these details here if you want to change the date or time.':data.error||'I couldn’t reach NYU’s room calendar just now. No booking has been made. Your session details are still here—try again in a moment.',roomRequest:plan.room,critical:true};}}}
 else if(plan.intent==='more-rooms'){const data=conversation.roomResults;if(data?.live){const start=conversation.roomOffset||3,next=data.rooms.slice(start,start+3);conversation.roomOffset=start+next.length;conversation.visibleRooms=next;reply={text:next.length?'Here are the next rooms for the same session.':'Those are all the matching rooms from the last check. Want to try another time?',rooms:next,roomRequest:conversation.room,checkedAt:data.checkedAt,critical:true};}else reply={text:'I still need the live NYU availability connection before I can list real rooms. Your session details are saved for this conversation.',critical:true};}
 else if(plan.intent==='select-room'){const room=conversation.visibleRooms?.[plan.index];chatBusy=false;if(room)return selectChatRoom(room.id);chatBusy=true;reply={text:'I don’t have a verified room at that position. Let’s check the session details and availability first.',critical:true};}
 else if(plan.intent==='more-books'){const start=conversation.bookOffset||3,next=conversation.lastBooks.slice(start,start+3);conversation.bookOffset=start+next.length;conversation.visibleBooks=next;reply=conversation.book.query?{text:next.length?'Here are a few more for the same search. You can also open the complete result list below.':'That’s the end of the current matches. You can open the full search below, or tell me what you’d like to change.',books:next,bookSearch:{...conversation.book}}:{text:'Of course—what book or topic are you looking for?'};}
 else if(plan.intent==='select-book'){const b=conversation.visibleBooks[plan.index];reply=b?{text:`${b.title}${b.subtitle?': '+b.subtitle:''} is by ${b.authors}. ${b.description?b.description.slice(0,330)+(b.description.length>330?'…':''):'The source didn’t provide a description.'}`,books:[b],bookDetail:b.id,bookSearch:{query:b.title,filters:{},scope:b.source==='Google Books'?'google':'opensquare'},critical:true}:{text:'Which title did you mean? You can type the name or choose a book card above.'};}
 else if(plan.intent==='books'){if(!plan.book.query){reply={text:'Sure—what’s the title, author, ISBN, or topic you have in mind?'};}else{conversation.topic='books';conversation.book=plan.book;const found=await retrieveChatBooks(plan.book),shown=found.rows.slice(0,3);reply=shown.length?{text:shown[0].exact||shown[0].isbnMatch?'I found an exact match. Here it is, along with any other useful results for your search.':plan.book.followup?'I’ve narrowed the same search using that detail. Here are the best matches in the retrieved records.':'Here are a few books that may be a useful starting point. Tell me what interests you about one of them, or what you’d like to narrow down.',books:shown.map(r=>r.book),bookSearch:{...conversation.book},critical:true}:{text:found.sourceError?'I couldn’t find a supported match in OpenSquare, and the broader book search couldn’t be reached just now. Do you have an author, ISBN, or another part of the title?':'I couldn’t find a good match in the records returned. Do you remember the author, an ISBN, or another word in the title?',bookSearch:{...conversation.book},critical:true};if(found.sourceError&&shown.length)reply.text+=' The broader search wasn’t reachable, so these suggestions are from the available OpenSquare records.';}}
 else reply={text:'No problem. Tell me a little about what you’re working on, and I’ll help you find a starting point.'};
 reply=await composeReply(message,reply);
 }catch{reply={text:'Something interrupted that lookup. I haven’t made any booking or changed your account. Could you try once more?',critical:true};}
 messages.push({role:'assistant',...reply});if(messages.length>60)messages.splice(1,messages.length-60);chatBusy=false;renderMessages();
}
function openChatSearch(index){const item=messages[index]?.bookSearch;if(!item?.query)return;Object.assign(state,{author:'',title:'',isbn:'',subject:'',from:'',to:'',language:'any',access:'any',scope:item.scope||'opensquare',...item.filters});$('#chat-panel').hidden=true;search(item.query);}
async function initAssistant(){try{const response=await fetch(apiPath('api/assistant/status'));if(response.ok){const data=await response.json();assistantMode=data.mode==='generative'?'generative':'contextual';}}catch{}const node=$('.chat-disclosure');if(node)node.textContent=assistantMode==='generative'?'Virtual helper · Replies use Google Gemini with source context · Never share account credentials':'Virtual helper · Conversation stays in this browser · Never share account credentials';}

function assessResults(){const top=results.slice(0,10);showDialog(`<div class="eyebrow">A FEEDBACK LOOP FOR BETTER DISCOVERY</div><h2>How well did these books answer your question?</h2><p>Query: <strong>${esc(currentQuery||'(browse)')}</strong>. Rate only the results you can judge. Saved in this browser; nothing is sent to NYU.</p><form id="assessment-form"><div class="form-grid"><label>Search goal<select name="intent"><option value="topic">Explore a topic</option><option value="known-item">Find a specific book</option><option value="service">Find a service</option></select></label><label>Time to find a useful book (seconds)<input name="seconds" type="number" min="0" max="86400" placeholder="Optional"></label><label>Expected title / resource<input name="expected" maxlength="300" placeholder="Optional"></label><label>Reviewer code<input name="reviewer" maxlength="80" placeholder="Optional anonymous code"></label></div><div class="assessment-rows">${top.map((r,i)=>`<label class="assessment-row"><span><b>${i+1}. ${esc(r.book.title)}</b><small>${esc(r.book.sources.join(' + '))}</small></span><select name="grade-${i}"><option value="">Not judged</option><option value="3">3 · Directly relevant</option><option value="2">2 · Relevant</option><option value="1">1 · Tangential</option><option value="0">0 · Off topic</option></select></label>`).join('')}</div><label class="assessment-notes">What worked or missed the mark?<textarea name="notes" rows="3" maxlength="2000" placeholder="No personal or account information, please."></textarea></label><p id="assessment-status" role="status"></p><div class="detail-actions"><button class="primary-button">Save assessment locally</button><button type="button" class="text-link" id="export-assessments">Export assessments (${assessments.length})</button></div></form>`);$('#assessment-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const grades=top.map((r,i)=>({bookId:r.book.id,title:r.book.title,source:r.book.sources,rank:i+1,grade:data['grade-'+i]===''?null:Number(data['grade-'+i]),score:r.score,semantic:r.semantic,lexical:r.lexical,model:r.semanticModel,weights:r.weights}));if(!grades.some(r=>r.grade!==null)){$('#assessment-status').textContent='Judge at least one result before saving.';return;}assessments.push({timestamp:new Date().toISOString(),query:currentQuery,intent:data.intent,seconds:data.seconds===''?null:Number(data.seconds),expected:data.expected,reviewer:data.reviewer,notes:data.notes,scope:state.scope,mode:state.mode,googleState,neuralEnabled:state.neural,filters:filters(),results:grades});try{localStorage.setItem('library-next-assessments',JSON.stringify(assessments));}catch{}$('#assessment-status').textContent='Assessment saved in this browser. Export it for the capstone evaluation.';$('#export-assessments').textContent=`Export assessments (${assessments.length})`;};$('#export-assessments').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({rubric:'0 off topic; 1 tangential; 2 relevant; 3 directly relevant; null not judged',notice:'Subjective judgments; use a held-out test set before model tuning.',assessments},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='library-next-assessments.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
function exportResults(){const cols=['rank','title','authors','year','isbn','sources','source_url','score','semantic_cosine','normalized_bm25','semantic_model','semantic_weight','keyword_weight','provider_weight','query'];const rows=results.map((r,i)=>[i+1,r.book.title,r.book.authors,r.book.year||'',r.book.isbn,r.book.sources.join('; '),r.book.sourceUrl,r.score.toFixed(6),r.semantic.toFixed(6),r.lexical.toFixed(6),r.semanticModel,r.weights.semantic,r.weights.lexical,r.weights.provider,currentQuery]);const csv=[cols,...rows].map(row=>row.map(v=>{let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='library-next-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Results exported with sources and ranking signals.');}
function bindPage(){if($('#search-form')){$('#search-form').onsubmit=e=>{e.preventDefault();search($('#query').value)};$('#neural-toggle').onchange=e=>{state.neural=e.target.checked;if(state.neural){toast('Neural mode downloads a public model (~25 MB) to this browser.');if(currentQuery)runNeural(lastRequest);}else{neuralScores=null;if(neuralWorker){neuralWorker.terminate();neuralWorker=null;}renderResults();}};}if($('#room-form'))$('#room-form').onsubmit=e=>{e.preventDefault();const plan=roomPlan({date:$('#room-date').value,start:$('#room-start').value,duration:$('#room-duration').value,people:$('#room-people').value});$('#room-error').textContent=plan.error||'';$('#room-plan').innerHTML=plan.error?'':`<div class="prepared-plan"><span class="eyebrow">YOUR SESSION PLAN · NOT A RESERVATION</span><h3>${esc(plan.date)} · ${esc(plan.start)} New York time</h3><p>${plan.people} people · ${plan.duration} minutes · Bobst group study</p><p>Availability has not been checked. Enter these details in NYU’s calendar, select an available room, and sign in with your NetID to complete your booking.</p>${link(plan.url,'Check availability at NYU','primary-link')}</div>`;};if($('#scope-filter')){for(const[key,id]of [['scope','scope-filter'],['access','access-filter'],['language','language-filter']])$('#'+id).onchange=e=>{state[key]=e.target.value;search($('#query').value)};for(const[key,id]of [['mode','mode-filter'],['sort','sort-filter'],['from','from-filter'],['to','to-filter']])$('#'+id).onchange=e=>{state[key]=e.target.value;if(state.from&&state.to&&Number(state.from)>Number(state.to)){toast('The start year must come before the end year.');return;}renderResults();};$('#reset-filters').onclick=()=>{Object.assign(state,{access:'any',language:'any',title:'',author:'',isbn:'',subject:'',from:'',to:'',sort:'relevance',mode:'hybrid'});search(currentQuery);};$('#export-results').onclick=exportResults;$('#assess-results').onclick=assessResults;$('#show-more').onclick=()=>{state.limit+=12;renderResults();};$('#fetch-more').onclick=()=>search(currentQuery,{more:true});}}
function bindGlobal(){$('#assistant-launch').onclick=openChat;$('#close-chat').onclick=()=>$('#chat-panel').hidden=true;$('#sources').onclick=sources;$('#close-dialog').onclick=()=>$('#dialog').close();$('#chat-form').onsubmit=e=>{e.preventDefault();if(chatBusy)return;const q=$('#chat-input').value;if(!q.trim())return;$('#chat-input').value='';chat(q);};$('#chat-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit();}});document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.chatResults!==undefined)openChatSearch(Number(d.chatResults));if(d.chatRoom)selectChatRoom(d.chatRoom);if(d.page){if(d.page==='saved'){currentQuery='';googleState='idle';pool=saved;page('saved');}else if(d.page==='search')page('search');else page(d.page);}if(d.query){if($('#dialog').open)$('#dialog').close();search(d.query);}if(d.scope){state.scope=d.scope;document.querySelectorAll('[data-scope]').forEach(x=>x.classList.toggle('active',x.dataset.scope===state.scope));}if(d.openAdvanced!==undefined)advanced();if(d.chat)openChat();if(d.ask)chat(d.ask);if(d.detail)bookDetail(d.detail);if(d.save){const book=findBook(d.save);if(!book)return;const exists=saved.some(s=>s.id===book.id);saved=exists?saved.filter(s=>s.id!==book.id):[...saved,book];try{localStorage.setItem('library-next-saved',JSON.stringify(saved));}catch{toast('Browser storage unavailable; saved for this session.');}$('#saved-count').textContent=saved.length;renderResults();if($('#dialog').open)bookDetail(book.id);toast(exists?'Removed from your bookshelf.':'Saved to your bookshelf.');}if(d.cite){const book=findBook(d.cite);try{await navigator.clipboard.writeText(`${book.authors}. (${book.year||'n.d.'}). ${book.title}${book.subtitle?': '+book.subtitle:''}. ${book.publisher||''}. ${book.sourceUrl}`);toast('Basic citation copied. Verify style and metadata before submission.');}catch{toast('Clipboard unavailable in this browser.');}}if(b.id==='retry-google')search(currentQuery);});}
async function init(){try{const base=import.meta.env.BASE_URL;const [c,m]=await Promise.all([fetch(`${base}books.json`).then(r=>{if(!r.ok)throw Error();return r.json()}),fetch(`${base}semantic-index.json`).then(r=>{if(!r.ok)throw Error();return r.json()})]);if(JSON.stringify(c.books.map(b=>b.id))!==JSON.stringify(m.bookIds))throw Error('Mismatched model');catalog=c.books.map(normalizeOpenSquare);model=m;const requestedScope=new URLSearchParams(location.search).get('scope');if(['all','google','opensquare'].includes(requestedScope))state.scope=requestedScope;corpusEngine=createEngine(c.books,m);pool=catalog;shell();initAssistant();const query=new URLSearchParams(location.search).get('q');if(query)search(query);}catch{$('#app').innerHTML='<div class="boot"><h1>The library could not open.</h1><p>The catalog files are unavailable. Please refresh or try again later.</p><button onclick="location.reload()">Try again</button></div>';}}
init();
